insert into public.collectives
  (num, name, photo, one_liner, full_bio, role, status)
values
  ('01', 'Yunsun Chung', '/team/01_Yunsun.jpg', '"A cool grandma in the making." Design educator and community advocate; the first IN-Collective.', 'I''m a cool grandma in the making, constantly learning and growing alongside you all as the very first IN-Collective at IN (INNOCO). My path as a design educator and community advocate has been fueled by a passion for connecting with others and fostering creative collaboration. My hands have planted seeds in both the literal and metaphorical gardens of innovation, always striving to nurture spaces where our collective ideas can flourish. In this journey of co-creation, I''ve learned that every voice adds value and every perspective can spark change. Here at INNOCO, I''m just one of many dedicated to weaving a tapestry of social innovation, where our combined efforts lead to a vibrant community and a more connected world.', 'Founder, CEO & Facilitation Lead', 'live'),
  ('02', 'Joanne Renaux', '/team/02_Joanne.jpg', 'Arts educator & illustrator. Co-founded IN; co-created Möbius Making.', 'I''m a passionate arts educator, illustrator, and facilitator for changemaking practices. My journey has been a tapestry of art and education, woven through my roles as a secondary school educator and arts instructor at Zayed University, Dubai. My heart lies in creative play, using visual storytelling as a tool to build community and facilitate meaningful conversations. With a vision to nurture a systems-thinking approach in education, I co-founded INNOCO. Here, we crafted the MEWE framework, a blueprint for changemaking pathways that intertwine individual creativity with collective action.', null, 'live'),
  ('03', 'Tanya Albus', '/team/03_Tanya.jpg', 'Journey designer & social-impact strategist; co-created Pathfinder.', 'Tanya Albus is a journey designer, social impact strategist, and facilitator for transformative practices. Her academic background is in medical sciences, having studied at the VU Medical Centre in Amsterdam. She is co-founder of Human of Health, a social enterprise focused on bringing healthcare back to its intended purpose — caring for health — through leadership schools, health hubs and events, and consulting services. Her focus has broadened beyond healthcare, looking at fundamental ways she can assist organizations, communities, and people in creating the journeys and ecosystems that make it possible for them to excel. She has studied yoga philosophy, ayurveda, and (quantum-based) holistic health sciences. Since 2021 she lives in Sweden with her family, and has recently pursued a degree in UX Design.', null, 'live'),
  ('04', 'Irene Pavlos', '/team/04_Irene.jpg', 'Companion to the young, ally to the elder. Community-builder at Noor, Dubai; co-created Two Wings.', 'A companion to the young and ally to the elder, with a heart dedicated to service. My journey with the UN has taken me across many paths, and now I find joy in nurturing the community at Noor in Dubai. In this role, I design spaces for conversations that matter, fostering virtues and actions aimed at bettering our world. Coordination is my forte — I organize tutor groups, manage children''s classes, steer junior youth groups, and facilitate study circles. Each setting is an opportunity to kindle understanding and encourage growth. To me, everyone is a divine friend; each meeting is a chance to extend love, sincerity, and perhaps, to melt a heart with kindness.', null, 'live'),
  ('05', 'Taejin Kim', '/team/05_Taejin.jpg', 'Trilingual educator (EN/中文/한국어); co-created Second Life.', 'I''m a dedicated mother of two beautiful kids. My trilingual prowess in English, Chinese, and Korean shone brightly when I facilitated crucial conversations at an international meeting in Taiwan. My translation skills bridged not just languages but hearts and minds. As an educator with a deep commitment to language teaching, I''ve had the joy of co-designing and translating at a youth social innovation workshop, earning accolades for my dual role. Balancing the demands of full-time teaching and motherhood, I bring passion and precision to empowering the young.', null, 'live'),
  ('06', 'Vahid Buehrer', '/team/06_Vahid.jpg', 'Educator & community-builder; co-created Second Life; runs a language school with Taejin.', 'I''m a father of two incredible kids, a community enthusiast, and an advocate for the transformative power of education. Alongside my wife Taejin, we run a school dedicated to teaching English, where we pour our joint expertise into every lesson, shaping the global citizens of tomorrow. But teaching languages is just one thread of my life''s fabric. I''ve volunteered in various community-building activities, from children''s classes to junior youth empowerment programs, always aiming to accompany and uplift those around me. My role extends to animating youth and young adults, steering study groups and workshops that inspire and guide them to uncover their own truths and potentials.', null, 'live'),
  ('07', 'Hojin Choi', '/team/07_Hojin.jpg', '"Bucket List Specialist." Author of Finally, Self-Discovery (2022); co-created Bucket List.', 'I''m your friendly Bucket List Specialist and facilitator of fun and transformative experiences. I wear many hats, but my true passion lies in helping people embark on their journey of self-discovery through my "Me-Finding Workshops." In 2023 alone, I''ve had the pleasure of conducting over 100 workshops for both individuals and corporations, guiding them toward their real goals and aspirations. In addition to my work in self-discovery, I''m no stranger to the world of finance, marketing, and digital transformation. With a background in sociology, I bring a unique perspective that combines analytical skill with a deep understanding of human dynamics. I''m also the author of the book "Finally, Self-Discovery," published in November 2022.', null, 'live'),
  ('08', 'Conrad Saldanha', '/team/08_Conrad.jpg', 'Lifelong learner; 32-year career (VP, The Times of India); co-created METANOIA; author of Seeking to Live.', 'I''m a lifelong learner and a bit of an adventure seeker. I''ve recently jumped into the artsy world of drawing and painting, and I''m also unraveling the mysteries of Sanskrit. My journey began at Mumbai University, studying management, and led to a fulfilling 32-year career, topping it off as Vice President at The Times of India. Retirement? Just a new chapter for me — I spent the next decade in education, sharing my experiences. I''ve been involved with the Archdiocese of Mumbai, helping in the 2001 Synod, and conducting workshops globally on "Vision, Mission, and Values." I also served on various advisory boards and am currently with the Asian Heart Institute''s Ethics Committee and the Consumer Guidance Society of India. In my downtime, I''m a blogger and author of "Seeking to Live."', null, 'live'),
  ('09', 'Bushra Ali', '/team/09_Bushra.jpg', 'Scholar-practitioner; research, EdTech, and non-profit leadership, USA.', 'I''ve built a career out of following many threads at once — research, entrepreneurship, EdTech, school improvement, and non-profit leadership — and finding where they meet. My work has centered on a single question: how do communities rise and organize to close real gaps, in education, healthcare, career development, and financial literacy? I care about a new vision for quality, affordable education, and about the kind of non-profit leadership that actually reaches people. For me, MEWE names something I''ve long practiced — that lifting one is lifting all.', null, 'live'),
  ('10', 'Saurav Dhakal', '/team/10_Saurav.jpg', 'Sustainability advocate & social entrepreneur, Nepal; Asia Exchange & UNC.', 'Saurav is a climate communicator and social entrepreneur dedicated to regenerative development and climate justice. He currently serves as Director of Sustainable Growth and Innovation at StoryCycle+, where he leads the T.E.A. Strategy — a holistic approach integrating Tourism, Energy, and Agriculture to build climate-resilient communities and promote green livelihoods. He has been engaged with IN since 2016, through the UNC project and the Food Revolution project, and is a passionate practitioner of MEWE.', null, 'live'),
  ('11', 'Shirin Mehri', '/team/11_Shirin.jpg', 'Scholar-practitioner in higher education & community development, USA.', 'A first-generation South Asian college graduate and Pakistani-Zoroastrian woman, Shirin brings a deep commitment to equity and justice — shaped by her own experience with identity, power, and privilege. With a decade of work across the UAE, Pakistan, and the US in gender, education, and community development, she has spent her career co-creating spaces where people''s dignity is honored. Her approach is rooted in restorative justice and community-building, supporting students'' growth, resilience, and sense of belonging. A colleague and friend since high school, Shirin has contributed so much to our shared practice — both as a scholar and as an IN-Collective.', null, 'live'),
  ('12', 'Tony Huyuhua', '/team/12_Tony.jpg', 'IN CTO; engineer & community practitioner, Taiwan; Asia Exchange.', 'Tony brings a rare mix of patience, warmth, and quiet determination — the kind of steady, goal-oriented presence that keeps a growing practice grounded. He supports the overall development of the initiative through cross-cultural collaboration, connecting community, education, and technology. He has already delivered the MEWE Möbius Making workshop in Chinese to Junyi High School students and teachers, and is now building networks that connect elementary school children, teachers, and parents. Easygoing and a little playful in person, Tony shows up for IN with real commitment — a friend whose steadiness helps the whole collective grow.', 'CTO / Technical Officer', 'live'),
  ('15', 'Aisha Khalid', '/team/15_Aisha.jpg', 'UAE-based design studio; exhibition design, branding, wayfinding; ran Creative Confidence.', 'Aisha Khalid Design is a UAE-based design studio with a passion for meaningful and effective design. We specialize in exhibition design, branding, wayfinding, signage, product design, and educational workshops. From concept to execution, creativity and design thinking inform everything we do.', null, 'live'),
  ('16', 'Noora Dakhan', '/team/16_Noora.jpg', 'Design + coaching; guides self-discovery through MEWE Workshops.', 'I''m your go-to for creative thinking and self-empowerment, passionate about lighting up that spark within you through our unique "MEWE Workshops." Blending my skills in design, business, and coaching, I''m here to guide you on an enlightening journey of self-discovery and personal growth. Think of me as your friendly guide in this adventure toward becoming the best version of yourself. I''m a horse lover at heart, a design enthusiast, and a coaching expert, all rolled into one.', null, 'live'),
  ('17', 'Mona Albeit', 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==', 'Artist, entrepreneur, and design strategist.', 'Bio coming soon.', 'Creative Director at IN', 'live'),
  ('18', 'To be announced', 'data:image/gif;base64,R0lGODlhAQABAAAAACH5BAEKAAEALAAAAAABAAEAAAICTAEAOw==', 'A new IN-Collective joining soon.', 'Details coming soon.', null, 'live')
